package za.co.gpbrij.cph.api; import za.co.gpbrij.cph.domain.*; import java.math.BigDecimal; import java.time.*;
public record PaymentView(String id,String company,String beneficiary,BigDecimal amount,String currency,String clientReference,LocalDate valueDate,PaymentStatus status,String rejectionReason,Instant createdAt,Instant updatedAt){ public static PaymentView from(Payment p){return new PaymentView(p.getId(),p.getCustomer().getCompanyName(),p.getBeneficiary().getName(),p.getAmount(),p.getCurrency(),p.getClientReference(),p.getValueDate(),p.getStatus(),p.getRejectionReason(),p.getCreatedAt(),p.getUpdatedAt());} }
